import {figures} from './figures.js';
// Coordinates are fractions of the unmodified textbook artwork, visually verified.
const S=(name,box,description,question)=>({name,box,description,question});
export const tours={
 families:{figure:'4.2',steps:[S('Epithelium',[0,.33,.36,.29],'A continuous sheet covers a surface. Compare the tightly packed cells with the matrix-rich connective tissue.','What makes this a sheet rather than a collection of scattered cells?'),S('Connective tissue',[.74,.43,.26,.37],'Cells sit within extracellular matrix. The matrix, not only cell shape, is central to identification.','Where is the material between the cells?'),S('Muscle tissue',[.74,.025,.26,.30],'Elongated contractile cells support movement. Use the muscle comparison to inspect real striations and nuclei.','Which structural feature supports contraction?'),S('Nervous tissue',[0,.025,.29,.24],'Branching neurons communicate; glial cells support the tissue. A single neuron is not an entire nervous tissue.','How does branching help a neuron receive information?')]},
 membranes:{figure:'4.4',steps:[S('Mucous membrane',[0,0,1,.33],'Mucous membranes line passages communicating with the exterior. They combine epithelium and underlying connective tissue.','Why is the digestive tract considered continuous with the exterior?'),S('Serous membrane',[0,.22,1,.38],'Serous membranes line closed ventral cavities and cover organs. A thin fluid film reduces friction between opposing surfaces.','Which layer is attached to the organ?'),S('Cutaneous membrane',[0,.43,1,.33],'The cutaneous membrane is skin: epidermis and the underlying dermis together.','Which part is epithelial and which part is connective tissue?'),S('Synovial membrane',[0,.57,1,.43],'Synovial membranes are connective tissue membranes associated with movable joints; they are not epithelial membranes.','Which member of this comparison lacks an epithelial layer?')]},
 origins:{figure:'4.3',steps:[S('Ectoderm',[0,0,1,.45],'Representative derivatives include epidermis and much of the nervous system. Follow the original table rather than a one-to-one tissue-family map.','Why are nervous tissue and epidermis grouped here?'),S('Mesoderm',[0,.43,1,.32],'Muscle and most connective tissues develop from mesoderm. Several organ systems contain mesodermal components.','Can an organ contain tissues derived from different germ layers?'),S('Endoderm',[0,.72,1,.28],'Endoderm forms much of the digestive and respiratory epithelial lining. Epithelia as a group can arise from all three germ layers.','Why is “all epithelium comes from ectoderm” incorrect?')]},
 junctions:{figure:'4.5',steps:[S('Tight junction',[0,0,.45,.36],'Sealing strands of transmembrane proteins restrict passage between adjacent cells. They do not form a channel between cytoplasms.','Where would a substance trying to pass between cells encounter a barrier?'),S('Gap junction',[.54,0,.46,.36],'Aligned connexons form channels between neighboring cytoplasms for ions and small molecules. The channel is the connection, not an empty tear.','How does this support coordinated activity?'),S('Desmosome & adherens',[0,.40,1,.36],'Desmosomes connect intermediate filaments through anchoring plaques. Adherens junctions connect actin. Both support mechanical attachment.','Which cytoskeletal component differs between these junctions?'),S('Hemidesmosome',[.12,.75,.45,.25],'Integrins attach a cell to the basal lamina. This is cell-to-matrix attachment, unlike the cell-to-cell desmosome above.','What is on the far side of this attachment?')]},
 secretion:{figure:'4.10',steps:[S('Merocrine · exocytosis',[0,0,1,.35],'Secretory vesicles fuse with the apical membrane. Product exits while the cell remains intact. Follow the three illustrated cells from preparation to release.','What leaves the cell, and what stays behind?'),S('Apocrine · apical portion',[0,.37,1,.30],'An apical portion pinches off with its product. Some cytoplasm and membrane are released; the entire cell is not the secretion.','How is this different from exocytosis?'),S('Holocrine · whole cell',[0,.69,1,.31],'The mature cell breaks down and becomes part of the secretion. Replacement cells are needed; sebaceous glands are a representative example.','Why must this mechanism depend on replacement cells?')]},
 regular:{figure:'4.15',steps:[S('Parallel bundles',[0,0,1,.48],'Dense regular connective tissue has largely parallel collagen bundles. Compare the drawing with the real micrograph; the orientations differ because the examples are presented differently.','Along which direction can these bundles best resist tension?'),S('Real tissue evidence',[.52,0,.48,.44],'Look for wavy eosinophilic collagen and thin dark fibroblast nuclei. The tissue is not a stack of uniformly spaced artificial lines.','Can you distinguish a collagen bundle from a nucleus?')]},
 irregular:{figure:'4.15',steps:[S('Interwoven bundles',[0,.50,1,.50],'Dense irregular connective tissue contains bundles running in multiple directions. The dermis is a representative location.','Why would this help skin resist pulls from several directions?'),S('Real tissue evidence',[.52,.51,.48,.44],'Follow several bundles through the image. Their directions change; do not mistake a dark nucleus for a whole fiber.','What evidence rules out one parallel arrangement?')]},
 elastic:{figure:'4.12',steps:[S('Fibers within the matrix',[0,0,.58,1],'The original drawing distinguishes elastic, collagen and reticular fibers in connective tissue proper. Elastic fibers support recoil; this mixed-tissue example is not a dedicated dense elastic specimen.','Which named fiber provides recoil?'),S('Compare drawing and specimen',[0,0,1,1],'Drawings separate structures for clarity. In a stained section, fiber types are not necessarily as easy to distinguish. Do not infer a fiber identity from color alone.','What can you identify confidently in the specimen?')]},
 cartilage:{figure:'4.16',steps:[S('Hyaline cartilage',[0,0,1,.34],'Chondrocytes occupy lacunae within a relatively glassy matrix. Fine collagen is present even when individual fibers are not resolved.','Does an apparently smooth matrix mean that collagen is absent?'),S('Fibrocartilage',[0,.34,1,.33],'Thick collagen bundles surround chondrocytes in lacunae. This organization helps withstand compression and tension.','How does the matrix differ from hyaline cartilage?'),S('Elastic cartilage',[0,.67,1,.33],'The matrix contains an elastic fiber network around lacunae, supporting flexible shape retention.','Why is this suited to the external ear?')]},
 skeletal:{figure:'4.18',steps:[S('Skeletal muscle · panel a',[0,0,1,.28],'Long parallel fibers show transverse striations and peripheral nuclei. Examine multiple fibers before deciding; a nucleus may not appear in every section.','Which combination distinguishes this from cardiac muscle?')]},
 smooth:{figure:'4.18',steps:[S('Smooth muscle · panel b',[0,.34,1,.29],'Look for elongated central nuclei and the absence of visible striations. Full spindle-shaped cell boundaries may be difficult to resolve in this section.','Which evidence is visible, rather than merely expected?')]},
 cardiac:{figure:'4.18',steps:[S('Cardiac muscle · panel c',[0,.69,1,.28],'Striations, central nuclei and a branching arrangement support cardiac muscle. Intercalated discs may not be clearly resolved in every field; do not label every dark line a disc.','What evidence can you use when an intercalated disc is not obvious?')]},
 signal:{figure:'4.19',steps:[S('Receive at dendrites',[.52,.51,.48,.49],'Dendrites provide receptive surfaces. The highlight follows the typical information-flow relationship; it is not an ion or an action potential traveling through the nucleus.','Why does branching increase the receptive surface?'),S('Integrate near the cell body',[.51,.50,.45,.50],'The soma supports cell maintenance and receives integrated input. Action potentials typically initiate near the axon initial segment, not in the nucleus.','Where does the axon begin relative to the cell body?'),S('Propagate along the axon',[.15,.53,.68,.41],'The moving guide follows the axon toward its terminals. It represents propagation, not a physical particle moving the entire length. This figure does not depict a myelin sheath.','How is a traveling electrical change different from one particle traversing the axon?'),S('Communicate at terminals',[0,.39,.35,.48],'The terminal branches contact other cells. Synaptic communication transfers information to a target; the exact mechanism is not resolved in this overview.','Which structure links this neuron to its next target?')]},
 support:{figure:'4.20',steps:[S('Glia and neurons together',[0,0,.44,1],'The textbook distinguishes neurons, astrocytes, microglia and an oligodendrocyte. Glia provide different support functions; they are not interchangeable decorations.','Which cells support the local environment, and which provide immune surveillance?'),S('Myelin in context',[0,0,1,1],'Oligodendrocytes make CNS myelin; Schwann cells make PNS myelin. This illustration highlights the CNS example.','Why should a Schwann-cell label not be placed on an oligodendrocyte?')]},
 healing:{figure:'4.21',steps:[S('Contain injury',[0,0,.43,1],'Clot formation limits blood loss. Inflammatory signals and recruited white blood cells support cleanup. The opening is not instantly restored.','Which visible structures show both containment and inflammation?'),S('Rebuild the wound',[.39,0,.32,1],'Fibroblasts deposit matrix, new vessels restore supply, and epithelial cells cover granulation tissue. These processes overlap rather than forming isolated timed steps.','Why does new tissue need a vascular supply?'),S('Remodel and mature',[.71,0,.29,1],'Restored epithelium covers underlying scar. Remodeling can improve strength without restoring all original tissue architecture or appendages.','Why does closure not necessarily mean complete regeneration?')]},
 outcomes:{figure:'4.21',steps:[S('Regeneration versus fibrosis',[.70,0,.30,1],'The restored surface and underlying scar illustrate different outcomes within the same wound. Regeneration replaces the original cell type; fibrosis deposits collagen-rich scar.','Which visible layer is restored, and where does the scar remain?')]}
};
export const labOptions={types:[['families','Tissue families'],['membranes','Membranes'],['origins','Germ layers']],epithelial:[['classifier','Layers & shape'],['junctions','Junction details'],['transitional','Transitional tissue'],['secretion','Secretion mechanisms']],connective:[['regular','Dense regular'],['irregular','Dense irregular'],['elastic','Matrix & fibers'],['cartilage','Cartilage']],muscle:[['skeletal','Skeletal specimen'],['cardiac','Cardiac specimen'],['smooth','Smooth specimen']],nervous:[['signal','Information flow'],['support','Glial support']],repair:[['healing','Healing sequence'],['outcomes','Repair outcomes']]};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rect(box,f){return [box[0]*f.width,box[1]*f.height,box[2]*f.width,box[3]*f.height];}
export function lab(module,{mode=labOptions[module][0][0],labels=true,step=0,layers=1,shape='cuboidal',secretion='merocrine',detail=true}={}){
 let tour=tours[mode],controls='';
 if(mode==='classifier'){
  const row=['squamous','cuboidal','columnar'].indexOf(shape),col=Number(layers)===1?0:1;
  tour={figure:'4.6',steps:[S(`${col?'Stratified':'Simple'} ${shape}`,[col?.41:.116,row*.323,.294,.323],col?'Identify the apical cells to name stratified epithelium. Basal cells may have a different shape. The textbook preserves that distinction.':'Every cell in a simple epithelial layer contacts the basal lamina. Classify the cell shape separately from the layer count.','Which cells should determine the shape part of the name?')]};
  controls=`<label>Layers <select id="layers"><option value="1" ${!col?'selected':''}>One</option><option value="3" ${col?'selected':''}>Several</option></select></label><label>Surface shape <select id="shape">${['squamous','cuboidal','columnar'].map(s=>`<option ${shape===s?'selected':''}>${s}</option>`).join('')}</select></label>`;
 }
 if(mode==='transitional')tour={figure:'4.8',steps:[S('Transitional epithelium',[0,.86,1,.14],'The textbook summary shows specialized stratified epithelium. During filling, superficial umbrella cells flatten and the tissue becomes thinner. Distension does not remove cells or convert it into simple epithelium.','What changes with distension, and what stays the same?')]};
 const f=figures.find(f=>f.id===tour.figure),i=((step%tour.steps.length)+tour.steps.length)%tour.steps.length,s=tour.steps[i];
 let box=detail?s.box:[0,0,1,1];
 if(labels===false){if(mode==='classifier'){const row=['squamous','cuboidal','columnar'].indexOf(shape);box=[.126,row===0?.17:.46,.269,row===0?.125:.165];}else if(mode==='regular')box=[.53,.01,.46,.42];else if(mode==='irregular')box=[.53,.52,.46,.42];}
 const view=rect(box,f),focus=rect(s.box,f),stroke=Math.max(2,f.width/400);
 let overlay=labels?`<rect class="focus-frame" x="${focus[0]+stroke}" y="${focus[1]+stroke}" width="${focus[2]-stroke*2}" height="${focus[3]-stroke*2}" rx="${stroke*2}" fill="none" stroke="#6550b9" stroke-width="${stroke}"/>`:'';
 if(labels&&mode==='signal'&&i===2)overlay+=`<path class="flow-trace" d="M ${f.width*.61} ${f.height*.75} Q ${f.width*.24} ${f.height*1.04} ${f.width*.235} ${f.height*.73} L ${f.width*.225} ${f.height*.62}" fill="none" stroke="#7650c9" stroke-width="${stroke*2}" pathLength="100"/>`;
 if(labels&&mode==='secretion'){
  const row=[.07,.405,.75][i],height=[.235,.23,.23][i];
  overlay+=`<g class="secretion-guide" aria-hidden="true">${[.205,.35,.495].map((x,n)=>`<rect class="process-focus" style="--phase:${n}" x="${f.width*x}" y="${f.height*row}" width="${f.width*.16}" height="${f.height*height}" rx="${stroke*5}" fill="none" stroke="#7650c9" stroke-width="${stroke*2}"/>`).join('')}</g>`;
 }
 const svg=`<svg class="textbook-study" viewBox="${view.join(' ')}" role="img" aria-label="${labels?escape(s.name+' — original textbook figure '+f.id):'Unlabeled textbook detail'}" xmlns="http://www.w3.org/2000/svg"><image href="${f.src}" x="0" y="0" width="${f.width}" height="${f.height}"/>${overlay}</svg>`;
 controls+=tour.steps.length>1?`<div class="tour-steps">${tour.steps.map((x,n)=>`<button data-tour-step="${n}" aria-pressed="${n===i}">${n+1}. ${escape(x.name)}</button>`).join('')}</div>`:'';
 return {title:s.name,caption:s.description,question:s.question,controls,svg,figure:f,step:i,steps:tour.steps.length};
}
